const [n, q] = readLine().split(' ').map(Number);
const a = readLine().split(' ').map(Number);
const out = [];
for (let i = 0; i < q; i++) {
  const x = Number(readLine());
  let lo = 0, hi = n; // first index with a[idx] > x
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (a[mid] <= x) lo = mid + 1; else hi = mid;
  }
  out.push(lo);
}
console.log(out.join('\n'));

